# our updated program here
import time
import numpy as np
import random
import math
from copy import deepcopy

class CVRPSolver:
    def __init__(self, coordinates: np.ndarray, distance_matrix: np.ndarray, demands: list, vehicle_capacity: int):
        """
        Initialize the CVRP solver.

        Args:
            coordinates: Numpy array of shape (n, 2) containing the (x, y) coordinates of each node, including the depot.
            distance_matrix: Numpy array of shape (n, n) containing pairwise distances between nodes.
            demands: List of integers representing the demand of each node (first node is typically the depot with zero demand).
            vehicle_capacity: Integer representing the maximum capacity of each vehicle.
        """
        self.coordinates = coordinates
        self.distance_matrix = distance_matrix
        self.demands = demands
        self.vehicle_capacity = vehicle_capacity
        self.n = len(coordinates)  # including depot node 0

    # --- implementation of Fragmented Memetic Reconstructor style solver ---
    def solve(self,
              time_limit: float = 5.0,
              seed: int = 0,
              params: dict = None) -> list:
        """
        Solve the Capacitated Vehicle Routing Problem (CVRP) using a fragmented memetic approach.

        Args:
            time_limit: time limit in seconds for the solver.
            seed: RNG seed.
            params: optional dictionary to tune behavior.

        Returns:
            Flat list route encoding with 0 as depot separators.
        """
        rnd = random.Random(seed)
        np.random.seed(seed)

        # default parameters
        if params is None:
            params = {}
        pop_size = params.get("pop_size", 30)
        init_frag_sizes = params.get("init_frag_sizes", [2, 3, 4])
        parent_strategy = params.get("parent_strategy", "tournament")  # or 'random'
        sample_budget = params.get("sample_budget", 10)
        assembler = params.get("assembler", "greedy")
        local_ops = params.get("local_ops", {"2opt_iters": 50, "relocate_iters": 50})
        replacement_strategy = params.get("replacement_strategy", "replace_worst")
        hotspot_criteria = params.get("hotspot_criteria", {"top_k": 3})
        intensify_budget = params.get("intensify_budget", 10)
        stagnation_limit = params.get("stagnation_limit", 50)
        frag_sizes = list(init_frag_sizes)
        max_routes = params.get("max_routes", self.n)  # upper bound

        # Utilities
        def evaluate(individual_routes):
            # individual_routes: list of routes (each route is list of customer indices excluding depot)
            total = 0.0
            for r in individual_routes:
                if len(r) == 0:
                    continue
                prev = 0
                for cust in r:
                    total += self.distance_matrix[prev, cust]
                    prev = cust
                total += self.distance_matrix[prev, 0]
            return total

        def route_demand(route):
            return sum(self.demands[i] for i in route)

        # Initialize population: randomized greedy pack
        def initialize_population(seed_pop):
            pop = []
            customers = list(range(1, self.n))
            for i in range(seed_pop):
                order = customers[:]
                rnd.shuffle(order)
                routes = []
                cur = []
                cur_load = 0
                for c in order:
                    d = self.demands[c]
                    if cur_load + d > self.vehicle_capacity:
                        if cur:
                            routes.append(cur)
                        cur = [c]
                        cur_load = d
                    else:
                        cur.append(c)
                        cur_load += d
                if cur:
                    routes.append(cur)
                pop.append(routes)
            return pop

        # Fragment pool: fragments are tuples of customers (subsequences)
        class FragmentPool:
            def __init__(self):
                self.pool = []  # list of dicts: {'seq': tuple, 'score': float, 'count': int, 'age': int}
                self.index = {}  # map seq -> idx

            def add(self, seq, score=1.0):
                key = tuple(seq)
                if key in self.index:
                    idx = self.index[key]
                    entry = self.pool[idx]
                    entry['count'] += 1
                    entry['score'] = (entry['score'] * (entry['count'] - 1) + score) / entry['count']
                    entry['age'] = 0
                else:
                    entry = {'seq': key, 'score': score, 'count': 1, 'age': 0}
                    self.index[key] = len(self.pool)
                    self.pool.append(entry)

            def sample(self, k, compat_model):
                if len(self.pool) == 0:
                    return []
                # weight by score and by compatibility (avg pairwise compat within seq)
                weights = []
                for e in self.pool:
                    base = max(1e-6, e['score'])
                    # compatibility: sum of compat for pairs in seq
                    seq = e['seq']
                    compat = 0.0
                    if len(seq) >= 2:
                        for a in seq:
                            for b in seq:
                                if a != b:
                                    compat += compat_model.get(a, {}).get(b, 0.0)
                        compat /= (len(seq) * max(1, (len(seq)-1)))
                    weights.append(base * (1.0 + compat))
                # normalize
                s = sum(weights)
                if s <= 0:
                    probs = [1.0 / len(weights)] * len(weights)
                else:
                    probs = [w / s for w in weights]
                chosen = rnd.choices(self.pool, weights=probs, k=min(k, len(self.pool)))
                return [list(e['seq']) for e in chosen]

            def decay(self):
                # age fragments, degrade score slightly for old entries
                new_pool = []
                new_index = {}
                for i, e in enumerate(self.pool):
                    e['age'] += 1
                    # optional aging removal
                    if e['age'] < 200:
                        # slight decay
                        e['score'] *= 0.999
                        new_index[e['seq']] = len(new_pool)
                        new_pool.append(e)
                self.pool = new_pool
                self.index = new_index

            def diversify(self, all_customers, sizes, rnd_local):
                # add some random fragments
                for s in sizes:
                    if s <= 0:
                        continue
                    seq = rnd_local.sample(all_customers, min(s, len(all_customers)))
                    self.add(seq, score=1.0)

            def update_with_candidate(self, fragments_used, candidate_score):
                for f in fragments_used:
                    self.add(f, score=candidate_score)

        # Compatibility model: nested dict default 0
        class CompatModel:
            def __init__(self, n):
                self.n = n
                self.co = {}  # co-occurrence weights dict of dict
                self.count = 0

            def online_update(self, fragments, score):
                # promote positive fragments: fragments are lists of nodes
                factor = 1.0 / (1.0 + score)
                for frag in fragments:
                    for i in frag:
                        for j in frag:
                            if i == j:
                                continue
                            self.co.setdefault(i, {})
                            self.co[i][j] = self.co[i].get(j, 0.0) + factor
                self.count += 1

            def get(self, a, b):
                return self.co.get(a, {}).get(b, 0.0)

        # Sample fragments from parents by extracting subsequences
        def sample_fragments_from_parents(parents, pool, compat, budget):
            fragments = []
            # prefer fragments from pool sampled plus some direct fragments from parents
            fragments.extend(pool.sample(max(1, budget//2), compat))
            # extract contiguous fragments from parent routes
            for p in parents:
                for r in p:
                    L = len(r)
                    if L == 0:
                        continue
                    # sample random subsequences
                    for _ in range(max(1, budget // max(1, len(parents)))):
                        a = rnd.randrange(0, L)
                        b = rnd.randrange(a, L)
                        frag = r[a:b+1]
                        if frag:
                            fragments.append(frag)
                            if len(fragments) >= budget:
                                return fragments
            return fragments[:budget]

        # Constraint-aware reconstruct: assemble fragments greedily into routes while respecting capacity
        def constraint_aware_reconstruct(fragments, all_customers, assembler_mode='greedy'):
            assigned = set()
            routes = []
            # First place fragments that fit
            # sort fragments by length desc (bigger pieces first)
            frags = sorted(fragments, key=lambda x: -len(x))
            for frag in frags:
                if any(c in assigned for c in frag):
                    continue
                load = sum(self.demands[c] for c in frag)
                placed = False
                # try to put into existing route if capacity allows
                for r in routes:
                    if route_demand(r) + load <= self.vehicle_capacity:
                        r.extend(frag)
                        for c in frag:
                            assigned.add(c)
                        placed = True
                        break
                if not placed:
                    # start new route
                    if load <= self.vehicle_capacity:
                        routes.append(list(frag))
                        for c in frag:
                            assigned.add(c)
            # fill remaining customers greedily by nearest insertion
            remaining = [c for c in all_customers if c not in assigned]
            # shuffle to add randomness
            rnd.shuffle(remaining)
            for c in remaining:
                d = self.demands[c]
                # try best insertion into existing route minimizing added distance
                best_r = None
                best_pos = None
                best_delta = None
                for r in routes:
                    if route_demand(r) + d > self.vehicle_capacity:
                        continue
                    # try append or insert positions
                    if len(r) == 0:
                        delta = self.distance_matrix[0, c] + self.distance_matrix[c, 0]
                        if best_delta is None or delta < best_delta:
                            best_r = r
                            best_pos = len(r)
                            best_delta = delta
                    else:
                        # try all insertion positions between nodes
                        prev_nodes = [0] + r
                        next_nodes = r + [0]
                        for idx in range(len(r)+1):
                            a = prev_nodes[idx]
                            b = next_nodes[idx]
                            delta = self.distance_matrix[a, c] + self.distance_matrix[c, b] - self.distance_matrix[a, b]
                            if best_delta is None or delta < best_delta:
                                best_r = r
                                best_pos = idx
                                best_delta = delta
                if best_r is not None:
                    best_r.insert(best_pos, c)
                else:
                    # create new route if possible
                    if d <= self.vehicle_capacity:
                        routes.append([c])
                    else:
                        # cannot satisfy capacity (shouldn't happen in valid CVRP), place alone
                        routes.append([c])
                assigned.add(c)
            # optionally merge small routes greedily to reduce count but obey capacity
            merged = True
            while merged:
                merged = False
                R = len(routes)
                if R <= 1:
                    break
                for i in range(len(routes)):
                    for j in range(i+1, len(routes)):
                        ri, rj = routes[i], routes[j]
                        if route_demand(ri) + route_demand(rj) <= self.vehicle_capacity:
                            # merge if reduces total distance
                            before = evaluate([ri]) + evaluate([rj])
                            merged_route = ri + rj
                            after = evaluate([merged_route])
                            if after <= before + 1e-9:
                                routes[i] = merged_route
                                routes.pop(j)
                                merged = True
                                break
                    if merged:
                        break
            return routes

        # Repair and normalize: ensure each customer appears once
        def repair_and_normalize(routes):
            # flatten to count
            counts = {}
            for r in routes:
                for c in r:
                    counts[c] = counts.get(c, 0) + 1
            # remove duplicates keeping first occurrence
            seen = set()
            new_routes = []
            for r in routes:
                nr = []
                for c in r:
                    if c not in seen:
                        nr.append(c)
                        seen.add(c)
                if len(nr) > 0:
                    new_routes.append(nr)
            # add missing customers
            missing = [c for c in range(1, self.n) if c not in seen]
            rnd.shuffle(missing)
            for c in missing:
                placed = False
                d = self.demands[c]
                # try to place into an existing route with capacity
                best_r = None
                best_delta = None
                for r in new_routes:
                    if route_demand(r) + d > self.vehicle_capacity:
                        continue
                    # append candidate
                    last = r[-1] if r else 0
                    delta = self.distance_matrix[last, c] + self.distance_matrix[c, 0] - self.distance_matrix[last, 0]
                    if best_delta is None or delta < best_delta:
                        best_delta = delta
                        best_r = r
                if best_r is not None:
                    best_r.append(c)
                else:
                    new_routes.append([c])
            # ensure no route empty and capacities respected (split if too big)
            final_routes = []
            for r in new_routes:
                if route_demand(r) <= self.vehicle_capacity:
                    final_routes.append(r)
                else:
                    # split greedily
                    cur = []
                    cur_load = 0
                    for c in r:
                        if cur_load + self.demands[c] > self.vehicle_capacity:
                            final_routes.append(cur)
                            cur = [c]
                            cur_load = self.demands[c]
                        else:
                            cur.append(c)
                            cur_load += self.demands[c]
                    if cur:
                        final_routes.append(cur)
            return final_routes

        # Local memetic refine: apply intra-route 2-opt and inter-route relocate
        def local_memetic_refine(routes, iterations):
            """
            Improved local memetic refine using best-improvement across three neighborhoods:
            - intra-route 2-opt (segment reversal)
            - inter-route relocate (single customer)
            - inter-route swap (single customer <-> single customer)

            Uses enclosing 'self' attributes for distances, demands, and capacity.
            """
            dist = self.distance_matrix
            cap = self.vehicle_capacity
            demands = self.demands

            def route_cost(r):
                if not r:
                    return 0.0
                c = dist[0, r[0]]
                for k in range(len(r) - 1):
                    c += dist[r[k], r[k + 1]]
                c += dist[r[-1], 0]
                return c

            def route_load(r):
                return sum(demands[c] for c in r)

            # shallow copy input routes
            best_routes = [list(r) for r in routes]
            route_costs = [route_cost(r) for r in best_routes]
            route_loads = [route_load(r) for r in best_routes]
            best_cost = sum(route_costs)

            it = 0
            EPS = 1e-12

            n_routes = len(best_routes)
            while it < iterations:
                n_routes = len(best_routes)
                best_delta = -EPS
                best_move = None

                # 1) Intra-route 2-opt (reverse segment)
                for ri in range(n_routes):
                    r = best_routes[ri]
                    L = len(r)
                    if L <= 2:
                        continue
                    # i is start index of segment, j is end index (inclusive)
                    for i in range(0, L - 1):
                        a = 0 if i == 0 else r[i - 1]
                        c = r[i]
                        for j in range(i + 1, L):
                            b = r[j]
                            d = 0 if j == L - 1 else r[j + 1]
                            # edges removed: a-c and b-d
                            removed = dist[a, c] + dist[b, d]
                            # edges added: a-b and c-d
                            added = dist[a, b] + dist[c, d]
                            delta = added - removed
                            if delta < best_delta:
                                best_delta = delta
                                best_move = {"type": "2opt", "ri": ri, "i": i, "j": j, "delta": delta}

                # 2) Inter-route relocate (single customer)
                for i in range(n_routes):
                    ri_list = best_routes[i]
                    Li = len(ri_list)
                    if Li == 0:
                        continue
                    for pos in range(Li):
                        c = ri_list[pos]
                        demand_c = demands[c]
                        prev_i = 0 if pos == 0 else ri_list[pos - 1]
                        next_i = 0 if pos == Li - 1 else ri_list[pos + 1]
                        removed_i = dist[prev_i, c] + dist[c, next_i]
                        added_i = dist[prev_i, next_i]
                        delta_removal = added_i - removed_i
                        for j in range(n_routes):
                            if i == j:
                                continue
                            # feasibility
                            if route_loads[j] + demand_c > cap:
                                continue
                            rj_list = best_routes[j]
                            Lj = len(rj_list)
                            if Lj == 0:
                                delta_ins = dist[0, c] + dist[c, 0]
                                total_delta = delta_removal + delta_ins
                                if total_delta < best_delta:
                                    best_delta = total_delta
                                    best_move = {
                                        "type": "relocate",
                                        "from": i,
                                        "to": j,
                                        "from_pos": pos,
                                        "to_pos": 0,
                                        "delta": total_delta,
                                        "empty_target": True,
                                    }
                            else:
                                # insertion positions 0..Lj (inserting at end allowed)
                                for ins in range(Lj + 1):
                                    prev_j = 0 if ins == 0 else rj_list[ins - 1]
                                    next_j = 0 if ins == Lj else rj_list[ins]
                                    added_j = dist[prev_j, c] + dist[c, next_j]
                                    removed_j = dist[prev_j, next_j]
                                    delta_ins = added_j - removed_j
                                    total_delta = delta_removal + delta_ins
                                    if total_delta < best_delta:
                                        best_delta = total_delta
                                        best_move = {
                                            "type": "relocate",
                                            "from": i,
                                            "to": j,
                                            "from_pos": pos,
                                            "to_pos": ins,
                                            "delta": total_delta,
                                            "empty_target": False,
                                        }

                # 3) Inter-route swap (one customer from route i with one from route j)
                for i in range(n_routes):
                    ri_list = best_routes[i]
                    Li = len(ri_list)
                    if Li == 0:
                        continue
                    for j in range(i + 1, n_routes):
                        rj_list = best_routes[j]
                        Lj = len(rj_list)
                        if Lj == 0:
                            continue
                        for pi in range(Li):
                            ci = ri_list[pi]
                            demand_ci = demands[ci]
                            prev_ai = 0 if pi == 0 else ri_list[pi - 1]
                            next_ai = 0 if pi == Li - 1 else ri_list[pi + 1]
                            for pj in range(Lj):
                                cj = rj_list[pj]
                                demand_cj = demands[cj]
                                # capacity feasibility after swap
                                load_i_after = route_loads[i] - demand_ci + demand_cj
                                load_j_after = route_loads[j] - demand_cj + demand_ci
                                if load_i_after > cap or load_j_after > cap:
                                    continue
                                prev_bj = 0 if pj == 0 else rj_list[pj - 1]
                                next_bj = 0 if pj == Lj - 1 else rj_list[pj + 1]
                                removed = (
                                    dist[prev_ai, ci] + dist[ci, next_ai] + dist[prev_bj, cj] + dist[cj, next_bj]
                                )
                                added = (
                                    dist[prev_ai, cj] + dist[cj, next_ai] + dist[prev_bj, ci] + dist[ci, next_bj]
                                )
                                delta = added - removed
                                if delta < best_delta:
                                    best_delta = delta
                                    best_move = {"type": "swap", "i": i, "j": j, "pi": pi, "pj": pj, "delta": delta}

                # If no improving move found, exit early
                if best_move is None:
                    break

                mv = best_move
                # Apply the chosen move. After application we recompute affected route costs and loads
                if mv["type"] == "2opt":
                    ri = mv["ri"]
                    i = mv["i"]
                    j = mv["j"]
                    r = best_routes[ri]
                    # perform in-place reversal
                    r[i : j + 1] = list(reversed(r[i : j + 1]))
                    # recompute cost for route
                    route_costs[ri] = route_cost(best_routes[ri])
                    best_cost = sum(route_costs)
                elif mv["type"] == "relocate":
                    frm = mv["from"]
                    to = mv["to"]
                    from_pos = mv["from_pos"]
                    to_pos = mv["to_pos"]
                    c = best_routes[frm][from_pos]
                    demand_c = demands[c]
                    # Remove element from source route
                    best_routes[frm].pop(from_pos)
                    route_loads[frm] -= demand_c
                    # If source became empty, remove that route entry
                    removed_src = False
                    if len(best_routes[frm]) == 0:
                        # remove empty route
                        best_routes.pop(frm)
                        route_costs.pop(frm)
                        route_loads.pop(frm)
                        removed_src = True
                        # adjust destination index if it was after the removed source
                        if to > frm:
                            to -= 1
                    else:
                        # recompute cost for source route
                        route_costs[frm] = route_cost(best_routes[frm])
                    # Insert into target route (handle empty_target which indicates insertion into an empty route slot)
                    if mv.get("empty_target", False):
                        # Insert a new route at index 'to' containing single node c
                        # If to is out of range (shouldn't normally happen), clamp it
                        if to < 0:
                            to = 0
                        if to > len(best_routes):
                            to = len(best_routes)
                        best_routes.insert(to, [c])
                        route_loads.insert(to, demand_c)
                        route_costs.insert(to, route_cost([c]))
                    else:
                        # Insert into existing route (to must be valid)
                        # to_pos is in [0 .. original Lj]; it remains valid unless we removed a route that was the same as target (we ensured frm != to)
                        if to < 0:
                            to = 0
                        if to >= len(best_routes):
                            # fallback: append as a new route (shouldn't normally happen)
                            best_routes.append([c])
                            route_loads.append(demand_c)
                            route_costs.append(route_cost([c]))
                        else:
                            # insert into route 'to' at position 'to_pos'
                            # If to_pos is greater than current length (possible if routes shifted), clamp to end
                            tp = to_pos
                            if tp < 0:
                                tp = 0
                            if tp > len(best_routes[to]):
                                tp = len(best_routes[to])
                            best_routes[to].insert(tp, c)
                            route_loads[to] += demand_c
                            route_costs[to] = route_cost(best_routes[to])
                    best_cost = sum(route_costs)
                elif mv["type"] == "swap":
                    i = mv["i"]
                    j = mv["j"]
                    pi = mv["pi"]
                    pj = mv["pj"]
                    # swap nodes
                    ci = best_routes[i][pi]
                    cj = best_routes[j][pj]
                    best_routes[i][pi], best_routes[j][pj] = cj, ci
                    # update loads
                    route_loads[i] = route_loads[i] - demands[ci] + demands[cj]
                    route_loads[j] = route_loads[j] - demands[cj] + demands[ci]
                    # recompute costs for affected routes
                    route_costs[i] = route_cost(best_routes[i])
                    route_costs[j] = route_cost(best_routes[j])
                    best_cost = sum(route_costs)
                else:
                    # unknown move; break safety
                    break

                it += 1

            # return only non-empty routes
            final = [r for r in best_routes if len(r) > 0]
            return final

        # Population replace
        def population_replace(pop, candidate, strategy="replace_worst"):
            cand_cost = evaluate(candidate)
            if strategy == "replace_worst":
                costs = [evaluate(p) for p in pop]
                worst_idx = int(np.argmax(costs))
                if cand_cost + 1e-9 < costs[worst_idx]:
                    pop[worst_idx] = candidate
            elif strategy == "random":
                idx = rnd.randrange(len(pop))
                pop[idx] = candidate
            elif strategy == "always_insert":
                # keep elitism by removing worst and inserting candidate
                costs = [evaluate(p) for p in pop]
                worst_idx = int(np.argmax(costs))
                pop[worst_idx] = candidate
            return pop

        # Identify hotspots: routes with highest cost per demand
        def identify_hotspots(pop, criteria):
            hotspots = []
            top_k = criteria.get("top_k", 3)
            scored = []
            for p in pop:
                for r in p:
                    d = route_demand(r)
                    c = 0.0
                    if len(r) > 0:
                        prev = 0
                        for cust in r:
                            c += self.distance_matrix[prev, cust]
                            prev = cust
                        c += self.distance_matrix[prev, 0]
                    score = c / max(1, d)
                    scored.append((score, r))
            scored.sort(reverse=True, key=lambda x: x[0])
            for i in range(min(top_k, len(scored))):
                hotspots.append(scored[i][1])
            return hotspots

        # Intensify on fragment: perform local search and add new fragments to pool
        def intensify_on_fragment(fragment, pool, compat, budget):
            # try to create variations by shuffling internal order and attempting to insert into pop best
            for _ in range(budget):
                frag = fragment[:]
                if len(frag) > 1:
                    a = rnd.randrange(len(frag))
                    b = rnd.randrange(len(frag))
                    frag[a], frag[b] = frag[b], frag[a]
                pool.add(frag, score=1.0)
                compat.online_update([frag], score=10.0)

        # Diversify pool and sizes
        def diversify_pool_and_sizes(pool, sizes):
            # add random fragments and mutate sizes
            all_customers = list(range(1, self.n))
            pool.diversify(all_customers, sizes, rnd)
            # tweak sizes a bit
            for i in range(len(sizes)):
                if rnd.random() < 0.3:
                    sizes[i] = max(1, sizes[i] + rnd.choice([-1, 1]))
            return pool, sizes

        # Stagnation detection
        def stagnation_detected(history, limit):
            return history >= limit

        # Decode function: from routes to flattened list with zeros separating routes
        def decode(individual_routes):
            flat = []
            for r in individual_routes:
                flat.append(0)
                flat.extend(r)
            flat.append(0)
            # compress possible duplicate zeros
            out = []
            for x in flat:
                if len(out) == 0:
                    out.append(x)
                else:
                    if not (out[-1] == 0 and x == 0):
                        out.append(x)
            if out[0] != 0:
                out.insert(0, 0)
            if out[-1] != 0:
                out.append(0)
            return out

        # --- Main algorithm initialization ---
        all_customers = list(range(1, self.n))
        POP = initialize_population(pop_size)
        POOL = FragmentPool()
        COMPAT_MODEL = CompatModel(self.n)

        # build initial fragments from population
        for p in POP:
            for r in p:
                L = len(r)
                for s in frag_sizes:
                    if s <= 0:
                        continue
                    if L >= s:
                        for i in range(0, L - s + 1):
                            seq = r[i:i+s]
                            POOL.add(seq, score=1.0)

        # best
        costs = [evaluate(p) for p in POP]
        best_idx = int(np.argmin(costs))
        best = deepcopy(POP[best_idx])
        best_cost = costs[best_idx]

        start_time = time.time()
        last_improve_time = start_time
        no_improve_iters = 0
        iter_count = 0

        # main loop
        while time.time() - start_time < time_limit:
            iter_count += 1
            # select parents
            parents = []
            if parent_strategy == "tournament":
                # tournament selection of 2 parents
                for _ in range(2):
                    a, b = rnd.randrange(len(POP)), rnd.randrange(len(POP))
                    if evaluate(POP[a]) < evaluate(POP[b]):
                        parents.append(deepcopy(POP[a]))
                    else:
                        parents.append(deepcopy(POP[b]))
            else:
                parents = [deepcopy(rnd.choice(POP)) for _ in range(2)]

            # sample fragments
            fragments = sample_fragments_from_parents(parents, POOL, COMPAT_MODEL.co, sample_budget)
            # reconstruct
            candidate = constraint_aware_reconstruct(fragments, all_customers, assembler)
            # repair/normalize
            candidate = repair_and_normalize(candidate)
            # local memetic refine
            candidate = local_memetic_refine(candidate, local_ops.get("2opt_iters", 50))
            # evaluate and update pool & compat model
            score = evaluate(candidate)
            POOL.update_with_candidate(fragments, score)
            COMPAT_MODEL.online_update(fragments, score)
            # population replacement
            POP = population_replace(POP, candidate, replacement_strategy)
            # hotspots and intensify
            hotspots = identify_hotspots(POP, hotspot_criteria)
            for h in hotspots:
                Intensify_iters = min(intensify_budget, max(1, len(h)))
                intensify_on_fragment(h, POOL, COMPAT_MODEL, Intensify_iters)
            # stagnation handling
            if score + 1e-9 < best_cost:
                best = deepcopy(candidate)
                best_cost = score
                last_improve_time = time.time()
                no_improve_iters = 0
            else:
                no_improve_iters += 1
            if no_improve_iters > stagnation_limit:
                POOL, frag_sizes = diversify_pool_and_sizes(POOL, frag_sizes)
                no_improve_iters = 0
            # POOL aging
            POOL.decay()
            # time break check
            if time.time() - start_time >= time_limit:
                break

        return decode(best)

import time
import numpy as np
import random
import math
from copy import deepcopy

class CVRPSolver:
    def __init__(self, coordinates: np.ndarray, distance_matrix: np.ndarray, demands: list, vehicle_capacity: int):
        """
        Initialize the CVRP solver.

        Args:
            coordinates: Numpy array of shape (n, 2) containing the (x, y) coordinates of each node, including the depot.
            distance_matrix: Numpy array of shape (n, n) containing pairwise distances between nodes.
            demands: List of integers representing the demand of each node (first node is typically the depot with zero demand).
            vehicle_capacity: Integer representing the maximum capacity of each vehicle.
        """
        self.coordinates = coordinates
        self.distance_matrix = distance_matrix
        self.demands = demands
        self.vehicle_capacity = vehicle_capacity
        self.n = len(coordinates)

    # --- helper functions implementing the coevolutionary bandit hypergraph metaheuristic ---
    def _route_cost(self, route):
        # route: list of nodes excluding depot endpoints (e.g., [1,4,3])
        if len(route) == 0:
            return 0.0
        cost = self.distance_matrix[0, route[0]]
        for i in range(len(route) - 1):
            cost += self.distance_matrix[route[i], route[i+1]]
        cost += self.distance_matrix[route[-1], 0]
        return cost

    def _solution_cost(self, solution_routes):
        # sum costs of routes
        return sum(self._route_cost(r) for r in solution_routes)

    def _is_feasible(self, solution_routes):
        for r in solution_routes:
            if sum(self.demands[i] for i in r) > self.vehicle_capacity:
                return False
        # check coverage
        visited = set()
        for r in solution_routes:
            visited.update(r)
        # exclude depot 0
        required = set(range(1, self.n))
        return visited == required

    def _repair_capacity(self, routes):
        # Ensure no route exceeds capacity. If it does, split greedily.
        new_routes = []
        for r in routes:
            if len(r) == 0:
                continue
            cur_route = []
            cur_load = 0
            for node in r:
                demand = self.demands[node]
                if cur_load + demand > self.vehicle_capacity:
                    if cur_route:
                        new_routes.append(cur_route)
                    cur_route = [node]
                    cur_load = demand
                    # If single node demand > capacity, we still place it (infeasible but will be penalized)
                else:
                    cur_route.append(node)
                    cur_load += demand
            if cur_route:
                new_routes.append(cur_route)
        # Ensure every customer present; if some missing, add them greedily
        present = set().union(*([set(r) for r in new_routes] if new_routes else []))
        missing = [i for i in range(1, self.n) if i not in present]
        for m in missing:
            placed = False
            # try to append to any route that can take it
            for r in new_routes:
                if sum(self.demands[x] for x in r) + self.demands[m] <= self.vehicle_capacity:
                    r.append(m)
                    placed = True
                    break
            if not placed:
                new_routes.append([m])
        return new_routes

    def _flatten_solution(self, routes):
        # convert list of routes to flat list with zeros delimiting routes
        flat = []
        for r in routes:
            flat.append(0)
            flat.extend(r)
        flat.append(0)
        # remove consecutive duplicate zeros (if any) except maintain route separators
        # ensure starts with 0 and ends with 0
        if flat[0] != 0:
            flat.insert(0, 0)
        if flat[-1] != 0:
            flat.append(0)
        return flat

    def _decode_flat(self, flat):
        # convert flat list with zeros into list of routes (exclude depot endpoints)
        routes = []
        cur = []
        for node in flat:
            if node == 0:
                if cur:
                    routes.append(cur)
                    cur = []
            else:
                cur.append(node)
        if cur:
            routes.append(cur)
        return routes

    def _init_islands(self, island_count, seed=None):
        rng = np.random.RandomState(seed)
        base_ops = ['crossover', 'merge', 'split', '2opt', 'relocate']
        islands = []
        for i in range(island_count):
            ops = deepcopy(base_ops)
            rng.shuffle(ops)
            focus = 'feasibility' if (i % 2 == 0) else 'cost'
            islands.append({
                'operator_portfolio': ops,
                'focus_profile': focus,
            })
        return islands

    def _init_population(self, islands, per_island_pop=8):
        # create simple greedy and randomized greedy solutions per island
        populations = []
        all_customers = list(range(1, self.n))
        for isl in islands:
            pop = []
            for p in range(per_island_pop):
                # randomized greedy: shuffle and pack according to capacity
                order = all_customers.copy()
                random.shuffle(order)
                routes = []
                cur = []
                cur_load = 0
                for node in order:
                    d = self.demands[node]
                    if cur_load + d > self.vehicle_capacity:
                        if cur:
                            routes.append(cur)
                        cur = [node]
                        cur_load = d
                    else:
                        cur.append(node)
                        cur_load += d
                if cur:
                    routes.append(cur)
                # local quick improvement: sort nodes in route by nearest neighbor heuristic
                for idx, r in enumerate(routes):
                    if len(r) <= 2:
                        continue
                    seq = [r[0]]
                    remaining = set(r[1:])
                    while remaining:
                        last = seq[-1]
                        next_node = min(remaining, key=lambda x: self.distance_matrix[last, x])
                        seq.append(next_node)
                        remaining.remove(next_node)
                    routes[idx] = seq
                routes = self._repair_capacity(routes)
                pop.append(routes)
            populations.append(pop)
        return populations

    def _init_bandits(self, islands):
        bandits = []
        for isl in islands:
            ops = isl['operator_portfolio']
            bandit = {op: {'value': 1.0, 'count': 0} for op in ops}
            bandits.append(bandit)
        return bandits

    def _select_parents(self, population, focus_profile):
        # tournament selection: prefer feasible and low cost depending on focus_profile
        k = min(3, len(population))
        candidates = random.sample(population, k)
        def score(sol):
            cost = self._solution_cost(sol)
            feasible = self._is_feasible(sol)
            if focus_profile == 'feasibility':
                return (0 if feasible else 1, cost)
            else:
                return (0 if feasible else 1, cost)
        parents = sorted(candidates, key=lambda s: score(s))[:2]
        return parents

    def _bandit_select(self, bandit, budget=1, eps=0.1):
        # simple epsilon-greedy: with prob eps choose random, else choose highest estimated value
        ops = list(bandit.keys())
        if random.random() < eps:
            chosen = random.choice(ops)
            return {'recombination': chosen, 'local_search': chosen}
        # choose by highest value (could tie)
        best = max(ops, key=lambda o: bandit[o]['value'])
        return {'recombination': best, 'local_search': best}

    def _ordered_crossover(self, p1, p2):
        # Flatten parents and perform ordered crossover on customer sequence.
        seq1 = [node for r in p1 for node in r]
        seq2 = [node for r in p2 for node in r]
        if not seq1 or not seq2:
            base = seq1 + seq2
            order = list(dict.fromkeys(base))
            # split greedily
            routes = []
            cur = []; cur_load=0
            for node in order:
                d = self.demands[node]
                if cur_load + d > self.vehicle_capacity:
                    if cur: routes.append(cur)
                    cur=[node]; cur_load=d
                else:
                    cur.append(node); cur_load+=d
            if cur: routes.append(cur)
            return routes
        a, b = sorted(random.sample(range(len(seq1)), 2))
        cut = seq1[a:b+1]
        child_seq = []
        leftover = [x for x in seq2 if x not in cut]
        child_seq = leftover[:a] + cut + leftover[a:]
        # ensure all customers present
        seen = set(child_seq)
        for node in range(1, self.n):
            if node not in seen:
                child_seq.append(node)
        # split into routes greedily
        routes = []
        cur = []; cur_load = 0
        for node in child_seq:
            d = self.demands[node]
            if cur_load + d > self.vehicle_capacity:
                if cur:
                    routes.append(cur)
                cur = [node]; cur_load = d
            else:
                cur.append(node); cur_load += d
        if cur: routes.append(cur)
        return routes

    def _merge_recombination(self, p1, p2):
        # merge routes that appear in both parents; otherwise take best of both by route cost
        routes = []
        all_routes = p1 + p2
        used = set()
        for r in all_routes:
            tup = tuple(r)
            if tup in used:
                continue
            # try to add r if capacity allows
            if sum(self.demands[x] for x in r) <= self.vehicle_capacity:
                routes.append(r.copy())
                used.add(tup)
        # add any missing customers
        present = set().union(*([set(r) for r in routes] if routes else []))
        for node in range(1, self.n):
            if node not in present:
                # append to route with most spare capacity or create new
                best_idx = None
                best_spare = -1
                for i, r in enumerate(routes):
                    spare = self.vehicle_capacity - sum(self.demands[x] for x in r)
                    if self.demands[node] <= spare and spare > best_spare:
                        best_spare = spare
                        best_idx = i
                if best_idx is not None:
                    routes[best_idx].append(node)
                else:
                    routes.append([node])
        return routes

    def _split_recombination(self, parents):
        # take a route from a random parent and split it/randomize
        p = random.choice(parents)
        if not p:
            # fallback to random greedy
            nodes = list(range(1, self.n))
            random.shuffle(nodes)
            routes = []
            cur = []; cur_load=0
            for node in nodes:
                d = self.demands[node]
                if cur_load + d > self.vehicle_capacity:
                    routes.append(cur)
                    cur=[node]; cur_load=d
                else:
                    cur.append(node); cur_load+=d
            if cur: routes.append(cur)
            return routes
        r = random.choice(p)
        # split r into two parts
        if len(r) <= 1:
            return self._merge_recombination(p, p)
        cut = random.randint(1, len(r)-1)
        part1 = r[:cut]; part2 = r[cut:]
        other_nodes = [x for p_ in parents for rr in p_ for x in rr if x not in part1 and x not in part2]
        # build routes
        routes = [part1, part2]
        # attach others greedily
        for node in other_nodes:
            placed = False
            for idx in range(len(routes)):
                if sum(self.demands[x] for x in routes[idx]) + self.demands[node] <= self.vehicle_capacity:
                    routes[idx].append(node)
                    placed = True
                    break
            if not placed:
                routes.append([node])
        return routes

    def _recombine_hypergraph(self, parents, op_name):
        # high-level recombination that tries to preserve shared substructures (approximation)
        if op_name == 'crossover':
            return self._ordered_crossover(parents[0], parents[1])
        elif op_name == 'merge':
            return self._merge_recombination(parents[0], parents[1])
        elif op_name == 'split':
            return self._split_recombination(parents)
        else:
            # default: crossover
            return self._ordered_crossover(parents[0], parents[1])

    def _local_search_2opt(self, routes, time_budget_ms=20):
        # apply simple 2-opt within each route
        end = time.time() + (time_budget_ms / 1000.0)
        for idx, r in enumerate(routes):
            improved = True
            while improved and time.time() < end:
                improved = False
                L = len(r)
                if L < 3:
                    break
                for i in range(L - 2):
                    for j in range(i + 2, L):
                        if j - i == 1:
                            continue
                        a, b = r[i], r[i+1]
                        c, d = r[j], r[(j+1) % L] if (j+1) < L else None
                        # compute delta
                        if d is None:
                            before = self.distance_matrix[a, b] + self.distance_matrix[c, 0]
                            after = self.distance_matrix[a, c] + self.distance_matrix[b, 0]
                        else:
                            before = self.distance_matrix[a, b] + self.distance_matrix[c, d]
                            after = self.distance_matrix[a, c] + self.distance_matrix[b, d]
                        if after + 1e-9 < before:
                            # perform 2-opt
                            newr = r[:i+1] + list(reversed(r[i+1:j+1])) + (r[j+1:] if j+1 < L else [])
                            routes[idx] = newr
                            r = newr
                            improved = True
                            break
                    if improved or time.time() >= end:
                        break
        return routes

    def _local_search_relocate(self, routes, time_budget_ms=20):
        # move single customers between routes to improve cost while respecting capacity
        end = time.time() + (time_budget_ms / 1000.0)
        routes = deepcopy(routes)
        improved = True
        while improved and time.time() < end:
            improved = False
            for i in range(len(routes)):
                r = routes[i]
                for j_idx in range(len(r)):
                    node = r[j_idx]
                    best_gain = 0
                    best_place = None
                    cur_cost = self._route_cost(r)
                    # try moving node to other route positions
                    for k in range(len(routes)):
                        if k == i:
                            continue
                        if sum(self.demands[x] for x in routes[k]) + self.demands[node] > self.vehicle_capacity:
                            continue
                        for pos in range(len(routes[k]) + 1):
                            # create candidate
                            new_r_i = r[:j_idx] + r[j_idx+1:]
                            new_r_k = routes[k][:pos] + [node] + routes[k][pos:]
                            gain = (self._route_cost(new_r_i) + self._route_cost(new_r_k)) - (self._route_cost(r) + self._route_cost(routes[k]))
                            if gain < best_gain - 1e-9:
                                best_gain = gain
                                best_place = (k, pos, new_r_i, new_r_k)
                    if best_place:
                        k, pos, new_ri, new_rk = best_place
                        routes[i] = new_ri
                        routes[k] = new_rk
                        improved = True
                        break
                if improved or time.time() >= end:
                    break
        # remove empty routes
        routes = [r for r in routes if r]
        return routes

    def _constraint_propagate_and_repair(self, routes):
        routes = self._repair_capacity(routes)
        # if duplicate nodes occur (shouldn't), fix
        seen = set()
        clean_routes = []
        for r in routes:
            newr = []
            for node in r:
                if node not in seen:
                    newr.append(node)
                    seen.add(node)
            if newr:
                clean_routes.append(newr)
        # add missing nodes
        missing = [i for i in range(1, self.n) if i not in seen]
        for m in missing:
            placed = False
            for r in clean_routes:
                if sum(self.demands[x] for x in r) + self.demands[m] <= self.vehicle_capacity:
                    r.append(m)
                    placed = True
                    break
            if not placed:
                clean_routes.append([m])
        return clean_routes

    def _evaluate(self, routes):
        cost = self._solution_cost(routes)
        feasible = self._is_feasible(routes)
        # Penalize infeasibility heavily proportional to overload
        overload = 0
        for r in routes:
            overload += max(0, sum(self.demands[i] for i in r) - self.vehicle_capacity)
        penalized_cost = cost + 1000.0 * overload + (0 if feasible else 500.0)
        return {'cost': cost, 'feasible': feasible, 'penalized': penalized_cost}

    def _archive_update(self, archive, candidate, evaluation):
        # archive holds best feasible solution (min cost)
        if evaluation['feasible']:
            if archive['best'] is None or evaluation['cost'] < archive['best_cost']:
                archive['best'] = deepcopy(candidate)
                archive['best_cost'] = evaluation['cost']
        # always store best penalized for selection diversity
        if archive['best_penalized'] is None or evaluation['penalized'] < archive['best_penalized_cost']:
            archive['best_penalized'] = deepcopy(candidate)
            archive['best_penalized_cost'] = evaluation['penalized']

    def _bandit_reward_function(self, old_eval, new_eval):
        # reward positive if penalized cost decreased or feasibility improved
        reward = old_eval['penalized'] - new_eval['penalized']
        # extra bonus if infeasible -> feasible
        if (not old_eval['feasible']) and new_eval['feasible']:
            reward += 1000.0
        return reward

    def _bandit_update(self, bandit, op_name, reward):
        entry = bandit.get(op_name)
        if entry is None:
            # add new op
            bandit[op_name] = {'value': 1.0, 'count': 0}
            entry = bandit[op_name]
        entry['count'] += 1
        # incremental update of estimated value (simple learning rate)
        lr = 1.0 / max(5, entry['count'])
        entry['value'] = (1 - lr) * entry['value'] + lr * reward

    def _migrate(self, populations, islands, policy='random'):
        # simple migration: swap a random individual between random island pairs
        island_count = len(populations)
        if island_count < 2:
            return populations
        a, b = random.sample(range(island_count), 2)
        if not populations[a] or not populations[b]:
            return populations
        ia = random.randrange(len(populations[a]))
        ib = random.randrange(len(populations[b]))
        populations[a][ia], populations[b][ib] = populations[b][ib], populations[a][ia]
        return populations

    def _adapt_operator_pools(self, islands, bandits, archive, adapt_rate=0.1):
        # occasionally replace the worst operator in an island with a copy of the best global operator
        # identify global best operator by average bandit value
        global_vals = {}
        for b in bandits:
            for op, entry in b.items():
                global_vals.setdefault(op, []).append(entry['value'])
        avg_vals = {op: (sum(vs)/len(vs)) for op, vs in global_vals.items()}
        if not avg_vals:
            return
        best_op = max(avg_vals.items(), key=lambda x: x[1])[0]
        for i, isl in enumerate(islands):
            if random.random() < adapt_rate:
                local_ops = isl['operator_portfolio']
                # replace worst local operator with best_op
                if local_ops:
                    # compute local values
                    local_vals = [(op, bandits[i].get(op, {'value':0})['value']) for op in local_ops]
                    worst_op = min(local_vals, key=lambda x: x[1])[0]
                    if worst_op != best_op:
                        # replace
                        isl['operator_portfolio'] = [best_op if o == worst_op else o for o in local_ops]
                        # ensure bandit entry exists
                        if best_op not in bandits[i]:
                            bandits[i][best_op] = {'value': 1.0, 'count': 0}

    # --- main solve method implementing the pseudocode loop ---
    def solve(self) -> list:
        """
        Solve the Capacitated Vehicle Routing Problem (CVRP).

        Returns:
            A one-dimensional list of integers representing the sequence of nodes visited by all vehicles.
        """
        # parameters (tunable)
        island_count = min(4, max(1, self.n // 5))
        per_island_pop = 8
        operator_budget = 1
        parallelism = min(2, island_count)
        migration_interval = 2.0  # seconds
        adapt_rate = 0.12
        time_limit = max(1.0, min(30.0, 0.1 * self.n))  # auto time limit based on instance size

        # init
        seed = int(time.time()) % (2**31 - 1)
        islands = self._init_islands(island_count, seed=seed)
        populations = self._init_population(islands, per_island_pop=per_island_pop)
        archive = {'best': None, 'best_cost': float('inf'), 'best_penalized': None, 'best_penalized_cost': float('inf')}
        bandits = self._init_bandits(islands)

        start = time.time()
        last_migration = start

        # Precompute evaluations for population to speed selection
        pop_evals = []
        for isl_pop in populations:
            evals = [self._evaluate(ind) for ind in isl_pop]
            pop_evals.append(evals)

        # main loop
        while time.time() - start < time_limit:
            # sample islands to operate on
            island_indices = random.sample(range(len(islands)), k=min(parallelism, len(islands)))
            for idx in island_indices:
                island = islands[idx]
                population = populations[idx]
                if not population:
                    continue
                # select parents
                parents = self._select_parents(population, island['focus_profile'])
                # bandit select operators
                ops = self._bandit_select(bandits[idx], budget=operator_budget)
                recomb_op = ops['recombination']
                local_op = ops['local_search']
                # recombine
                offspring = self._recombine_hypergraph(parents, recomb_op)
                # repair
                offspring = self._constraint_propagate_and_repair(offspring)
                # local search
                if local_op == '2opt':
                    offspring = self._local_search_2opt(offspring, time_budget_ms=20)
                elif local_op == 'relocate':
                    offspring = self._local_search_relocate(offspring, time_budget_ms=20)
                else:
                    # minor improvement by 2opt as default
                    offspring = self._local_search_2opt(offspring, time_budget_ms=10)
                # evaluate
                new_eval = self._evaluate(offspring)
                # update archive
                self._archive_update(archive, offspring, new_eval)
                # compute baseline old evaluation: use best penalized in island population as baseline
                # pick parent[0] evaluation if available
                old_eval = self._evaluate(parents[0])
                # reward
                reward = self._bandit_reward_function(old_eval, new_eval)
                # update bandit
                self._bandit_update(bandits[idx], recomb_op, reward)
                # insert offspring into population (replace worst)
                # find worst index by penalized cost
                worst_idx = max(range(len(population)), key=lambda i: self._evaluate(population[i])['penalized'])
                populations[idx][worst_idx] = offspring
                # update pop_evals for this island
                pop_evals[idx] = [self._evaluate(ind) for ind in populations[idx]]

            # migration
            now = time.time()
            if now - last_migration > migration_interval:
                populations = self._migrate(populations, islands)
                last_migration = now

            # adapt operator pools
            self._adapt_operator_pools(islands, bandits, archive, adapt_rate=adapt_rate)

        # decode best solution from archive
        best_routes = archive['best']
        if best_routes is None:
            # fallback to best penalized
            best_routes = archive['best_penalized'] if archive['best_penalized'] is not None else self._init_population(islands, per_island_pop=1)[0]

        flat = self._flatten_solution(best_routes)
        # ensure requirements: start and end at depot, visits all customers exactly once
        # final sanity check/fix
        routes = self._decode_flat(flat)
        routes = self._constraint_propagate_and_repair(routes)
        final_flat = self._flatten_solution(routes)
        return final_flat

# our updated program here
import time
import numpy as np
import random
import math
from copy import deepcopy

class CVRPSolver:
    def __init__(self, coordinates: np.ndarray, distance_matrix: np.ndarray, demands: list, vehicle_capacity: int):
        """
        Initialize the CVRP solver.

        Args:
            coordinates: Numpy array of shape (n, 2) containing the (x, y) coordinates of each node, including the depot.
            distance_matrix: Numpy array of shape (n, n) containing pairwise distances between nodes.
            demands: List of integers representing the demand of each node (first node is typically the depot with zero demand).
            vehicle_capacity: Integer representing the maximum capacity of each vehicle.
        """
        self.coordinates = coordinates
        self.distance_matrix = distance_matrix
        self.demands = demands
        self.vehicle_capacity = vehicle_capacity
        self.n = len(coordinates)

    # --- helper functions implementing the coevolutionary bandit hypergraph metaheuristic ---
    def _route_cost(self, route):
        # route: list of nodes excluding depot endpoints (e.g., [1,4,3])
        if len(route) == 0:
            return 0.0
        cost = self.distance_matrix[0, route[0]]
        for i in range(len(route) - 1):
            cost += self.distance_matrix[route[i], route[i+1]]
        cost += self.distance_matrix[route[-1], 0]
        return cost

    def _solution_cost(self, solution_routes):
        # sum costs of routes
        return sum(self._route_cost(r) for r in solution_routes)

    def _is_feasible(self, solution_routes):
        for r in solution_routes:
            if sum(self.demands[i] for i in r) > self.vehicle_capacity:
                return False
        # check coverage
        visited = set()
        for r in solution_routes:
            visited.update(r)
        # exclude depot 0
        required = set(range(1, self.n))
        return visited == required

    def _repair_capacity(self, routes):
        # Ensure no route exceeds capacity. If it does, split greedily.
        new_routes = []
        for r in routes:
            if len(r) == 0:
                continue
            cur_route = []
            cur_load = 0
            for node in r:
                demand = self.demands[node]
                if cur_load + demand > self.vehicle_capacity:
                    if cur_route:
                        new_routes.append(cur_route)
                    cur_route = [node]
                    cur_load = demand
                    # If single node demand > capacity, we still place it (infeasible but will be penalized)
                else:
                    cur_route.append(node)
                    cur_load += demand
            if cur_route:
                new_routes.append(cur_route)
        # Ensure every customer present; if some missing, add them greedily
        present = set().union(*([set(r) for r in new_routes] if new_routes else []))
        missing = [i for i in range(1, self.n) if i not in present]
        for m in missing:
            placed = False
            # try to append to any route that can take it
            for r in new_routes:
                if sum(self.demands[x] for x in r) + self.demands[m] <= self.vehicle_capacity:
                    r.append(m)
                    placed = True
                    break
            if not placed:
                new_routes.append([m])
        return new_routes

    def _flatten_solution(self, routes):
        # convert list of routes to flat list with zeros delimiting routes
        flat = []
        for r in routes:
            flat.append(0)
            flat.extend(r)
        flat.append(0)
        # remove consecutive duplicate zeros (if any) except maintain route separators
        # ensure starts with 0 and ends with 0
        if flat[0] != 0:
            flat.insert(0, 0)
        if flat[-1] != 0:
            flat.append(0)
        return flat

    def _decode_flat(self, flat):
        # convert flat list with zeros into list of routes (exclude depot endpoints)
        routes = []
        cur = []
        for node in flat:
            if node == 0:
                if cur:
                    routes.append(cur)
                    cur = []
            else:
                cur.append(node)
        if cur:
            routes.append(cur)
        return routes

    def _init_islands(self, island_count, seed=None):
        rng = np.random.RandomState(seed)
        base_ops = ['crossover', 'merge', 'split', '2opt', 'relocate']
        islands = []
        for i in range(island_count):
            ops = deepcopy(base_ops)
            rng.shuffle(ops)
            focus = 'feasibility' if (i % 2 == 0) else 'cost'
            islands.append({
                'operator_portfolio': ops,
                'focus_profile': focus,
            })
        return islands

    def _init_population(self, islands, per_island_pop=8):
        # create simple greedy and randomized greedy solutions per island
        populations = []
        all_customers = list(range(1, self.n))
        for isl in islands:
            pop = []
            for p in range(per_island_pop):
                # randomized greedy: shuffle and pack according to capacity
                order = all_customers.copy()
                random.shuffle(order)
                routes = []
                cur = []
                cur_load = 0
                for node in order:
                    d = self.demands[node]
                    if cur_load + d > self.vehicle_capacity:
                        if cur:
                            routes.append(cur)
                        cur = [node]
                        cur_load = d
                    else:
                        cur.append(node)
                        cur_load += d
                if cur:
                    routes.append(cur)
                # local quick improvement: sort nodes in route by nearest neighbor heuristic
                for idx, r in enumerate(routes):
                    if len(r) <= 2:
                        continue
                    seq = [r[0]]
                    remaining = set(r[1:])
                    while remaining:
                        last = seq[-1]
                        next_node = min(remaining, key=lambda x: self.distance_matrix[last, x])
                        seq.append(next_node)
                        remaining.remove(next_node)
                    routes[idx] = seq
                routes = self._repair_capacity(routes)
                pop.append(routes)
            populations.append(pop)
        return populations

    def _init_bandits(self, islands):
        bandits = []
        for isl in islands:
            ops = isl['operator_portfolio']
            bandit = {op: {'value': 1.0, 'count': 0} for op in ops}
            bandits.append(bandit)
        return bandits

    def _select_parents(self, population, focus_profile):
        # tournament selection: prefer feasible and low cost depending on focus_profile
        k = min(3, len(population))
        candidates = random.sample(population, k)
        def score(sol):
            cost = self._solution_cost(sol)
            feasible = self._is_feasible(sol)
            if focus_profile == 'feasibility':
                return (0 if feasible else 1, cost)
            else:
                return (0 if feasible else 1, cost)
        parents = sorted(candidates, key=lambda s: score(s))[:2]
        return parents

    def _bandit_select(self, bandit, budget=1, eps=0.1):
        # simple epsilon-greedy: with prob eps choose random, else choose highest estimated value
        ops = list(bandit.keys())
        if random.random() < eps:
            chosen = random.choice(ops)
            return {'recombination': chosen, 'local_search': chosen}
        # choose by highest value (could tie)
        best = max(ops, key=lambda o: bandit[o]['value'])
        return {'recombination': best, 'local_search': best}

    def _ordered_crossover(self, p1, p2):
        # Flatten parents and perform ordered crossover on customer sequence.
        seq1 = [node for r in p1 for node in r]
        seq2 = [node for r in p2 for node in r]
        if not seq1 or not seq2:
            base = seq1 + seq2
            order = list(dict.fromkeys(base))
            # split greedily
            routes = []
            cur = []; cur_load=0
            for node in order:
                d = self.demands[node]
                if cur_load + d > self.vehicle_capacity:
                    if cur: routes.append(cur)
                    cur=[node]; cur_load=d
                else:
                    cur.append(node); cur_load+=d
            if cur: routes.append(cur)
            return routes
        a, b = sorted(random.sample(range(len(seq1)), 2))
        cut = seq1[a:b+1]
        child_seq = []
        leftover = [x for x in seq2 if x not in cut]
        child_seq = leftover[:a] + cut + leftover[a:]
        # ensure all customers present
        seen = set(child_seq)
        for node in range(1, self.n):
            if node not in seen:
                child_seq.append(node)
        # split into routes greedily
        routes = []
        cur = []; cur_load = 0
        for node in child_seq:
            d = self.demands[node]
            if cur_load + d > self.vehicle_capacity:
                if cur:
                    routes.append(cur)
                cur = [node]; cur_load = d
            else:
                cur.append(node); cur_load += d
        if cur: routes.append(cur)
        return routes

    def _merge_recombination(self, p1, p2):
        # merge routes that appear in both parents; otherwise take best of both by route cost
        routes = []
        all_routes = p1 + p2
        used = set()
        for r in all_routes:
            tup = tuple(r)
            if tup in used:
                continue
            # try to add r if capacity allows
            if sum(self.demands[x] for x in r) <= self.vehicle_capacity:
                routes.append(r.copy())
                used.add(tup)
        # add any missing customers
        present = set().union(*([set(r) for r in routes] if routes else []))
        for node in range(1, self.n):
            if node not in present:
                # append to route with most spare capacity or create new
                best_idx = None
                best_spare = -1
                for i, r in enumerate(routes):
                    spare = self.vehicle_capacity - sum(self.demands[x] for x in r)
                    if self.demands[node] <= spare and spare > best_spare:
                        best_spare = spare
                        best_idx = i
                if best_idx is not None:
                    routes[best_idx].append(node)
                else:
                    routes.append([node])
        return routes

    def _split_recombination(self, parents):
        # take a route from a random parent and split it/randomize
        p = random.choice(parents)
        if not p:
            # fallback to random greedy
            nodes = list(range(1, self.n))
            random.shuffle(nodes)
            routes = []
            cur = []; cur_load=0
            for node in nodes:
                d = self.demands[node]
                if cur_load + d > self.vehicle_capacity:
                    routes.append(cur)
                    cur=[node]; cur_load=d
                else:
                    cur.append(node); cur_load+=d
            if cur: routes.append(cur)
            return routes
        r = random.choice(p)
        # split r into two parts
        if len(r) <= 1:
            return self._merge_recombination(p, p)
        cut = random.randint(1, len(r)-1)
        part1 = r[:cut]; part2 = r[cut:]
        other_nodes = [x for p_ in parents for rr in p_ for x in rr if x not in part1 and x not in part2]
        # build routes
        routes = [part1, part2]
        # attach others greedily
        for node in other_nodes:
            placed = False
            for idx in range(len(routes)):
                if sum(self.demands[x] for x in routes[idx]) + self.demands[node] <= self.vehicle_capacity:
                    routes[idx].append(node)
                    placed = True
                    break
            if not placed:
                routes.append([node])
        return routes

    def _recombine_hypergraph(self, parents, op_name):
        # high-level recombination that tries to preserve shared substructures (approximation)
        if op_name == 'crossover':
            return self._ordered_crossover(parents[0], parents[1])
        elif op_name == 'merge':
            return self._merge_recombination(parents[0], parents[1])
        elif op_name == 'split':
            return self._split_recombination(parents)
        else:
            # default: crossover
            return self._ordered_crossover(parents[0], parents[1])

    def _local_search_2opt(self, routes, time_budget_ms=20):
        # apply simple 2-opt within each route
        end = time.time() + (time_budget_ms / 1000.0)
        for idx, r in enumerate(routes):
            improved = True
            while improved and time.time() < end:
                improved = False
                L = len(r)
                if L < 3:
                    break
                for i in range(L - 2):
                    for j in range(i + 2, L):
                        if j - i == 1:
                            continue
                        a, b = r[i], r[i+1]
                        c, d = r[j], r[(j+1) % L] if (j+1) < L else None
                        # compute delta
                        if d is None:
                            before = self.distance_matrix[a, b] + self.distance_matrix[c, 0]
                            after = self.distance_matrix[a, c] + self.distance_matrix[b, 0]
                        else:
                            before = self.distance_matrix[a, b] + self.distance_matrix[c, d]
                            after = self.distance_matrix[a, c] + self.distance_matrix[b, d]
                        if after + 1e-9 < before:
                            # perform 2-opt
                            newr = r[:i+1] + list(reversed(r[i+1:j+1])) + (r[j+1:] if j+1 < L else [])
                            routes[idx] = newr
                            r = newr
                            improved = True
                            break
                    if improved or time.time() >= end:
                        break
        return routes

    # Optimized _local_search_relocate function replaced here
    # Your new function
    def _local_search_relocate(self, routes, time_budget_ms=20):
        """
        Best-improvement relocate variant:
        - Searches all feasible single-node relocations within the time budget and applies the best one each iteration.
        - Uses incremental delta calculations (no full route recomputation each candidate).
        - Repeats until no improving relocation is found or time runs out.
        """
        end = time.time() + (time_budget_ms / 1000.0)
        routes = deepcopy(routes)
        if not routes:
            return routes

        dm = self.distance_matrix
        demands = self.demands
        cap = self.vehicle_capacity

        def route_cost_quick(r):
            if not r:
                return 0.0
            c = dm[0, r[0]]
            for a, b in zip(r, r[1:]):
                c += dm[a, b]
            c += dm[r[-1], 0]
            return c

        # initial loads and costs
        loads = [sum(demands[x] for x in r) for r in routes]
        costs = [route_cost_quick(r) for r in routes]

        improved = True
        # small epsilon for floating comparisons
        eps = 1e-9

        while improved and time.time() < end:
            improved = False
            best_move = None
            best_gain = 1e-12  # we look for gain < 0 (negative gain reduces cost)

            # scan all possible relocations to find the best one
            for i, r in enumerate(routes):
                if time.time() >= end:
                    break
                L = len(r)
                if L == 0:
                    continue
                for j, node in enumerate(r):
                    if time.time() >= end:
                        break
                    node_d = demands[node]
                    old_cost_i = costs[i]

                    # compute delta on origin route when removing node
                    if L == 1:
                        delta_i = -old_cost_i
                    else:
                        if j == 0:
                            nxt = r[1]
                            before = dm[0, node] + dm[node, nxt]
                            after = dm[0, nxt]
                        elif j == L - 1:
                            prev = r[j - 1]
                            before = dm[prev, node] + dm[node, 0]
                            after = dm[prev, 0]
                        else:
                            prev = r[j - 1]
                            nxt = r[j + 1]
                            before = dm[prev, node] + dm[node, nxt]
                            after = dm[prev, nxt]
                        delta_i = after - before

                    # Try moving node to every other route and position
                    for k, rk in enumerate(routes):
                        if k == i:
                            continue
                        if loads[k] + node_d > cap:
                            continue
                        K = len(rk)
                        old_cost_k = costs[k]
                        # empty target route
                        if K == 0:
                            delta_k = dm[0, node] + dm[node, 0]
                            gain = delta_i + delta_k
                            if gain < best_gain - eps:
                                best_gain = gain
                                best_move = (i, j, k, 0, delta_i, delta_k)
                        else:
                            # insert at position 0
                            before = dm[0, rk[0]]
                            after = dm[0, node] + dm[node, rk[0]]
                            delta_k = after - before
                            gain = delta_i + delta_k
                            if gain < best_gain - eps:
                                best_gain = gain
                                best_move = (i, j, k, 0, delta_i, delta_k)
                            # middle positions
                            for pos in range(1, K):
                                prev = rk[pos - 1]
                                nxt = rk[pos]
                                before = dm[prev, nxt]
                                after = dm[prev, node] + dm[node, nxt]
                                delta_k = after - before
                                gain = delta_i + delta_k
                                if gain < best_gain - eps:
                                    best_gain = gain
                                    best_move = (i, j, k, pos, delta_i, delta_k)
                            # insert at end
                            before = dm[rk[-1], 0]
                            after = dm[rk[-1], node] + dm[node, 0]
                            delta_k = after - before
                            gain = delta_i + delta_k
                            if gain < best_gain - eps:
                                best_gain = gain
                                best_move = (i, j, k, K, delta_i, delta_k)

            # if found an improving move, apply the best one
            if best_move and time.time() < end:
                i, j, k, pos, d_i, d_k = best_move
                # Extract the node (recompute because routes may have changed slightly in time, but we hold to indices)
                node = routes[i][j]
                node_d = demands[node]
                # remove from origin route
                del routes[i][j]
                loads[i] -= node_d
                costs[i] += d_i
                # insert into target route at requested position
                routes[k].insert(pos, node)
                loads[k] += node_d
                costs[k] += d_k
                improved = True
                # continue to next iteration to recompute deltas fresh
            else:
                break

        # remove empty routes
        routes = [r for r in routes if r]
        return routes

    def _constraint_propagate_and_repair(self, routes):
        routes = self._repair_capacity(routes)
        # if duplicate nodes occur (shouldn't), fix
        seen = set()
        clean_routes = []
        for r in routes:
            newr = []
            for node in r:
                if node not in seen:
                    newr.append(node)
                    seen.add(node)
            if newr:
                clean_routes.append(newr)
        # add missing nodes
        missing = [i for i in range(1, self.n) if i not in seen]
        for m in missing:
            placed = False
            for r in clean_routes:
                if sum(self.demands[x] for x in r) + self.demands[m] <= self.vehicle_capacity:
                    r.append(m)
                    placed = True
                    break
            if not placed:
                clean_routes.append([m])
        return clean_routes

    def _evaluate(self, routes):
        cost = self._solution_cost(routes)
        feasible = self._is_feasible(routes)
        # Penalize infeasibility heavily proportional to overload
        overload = 0
        for r in routes:
            overload += max(0, sum(self.demands[i] for i in r) - self.vehicle_capacity)
        penalized_cost = cost + 1000.0 * overload + (0 if feasible else 500.0)
        return {'cost': cost, 'feasible': feasible, 'penalized': penalized_cost}

    def _archive_update(self, archive, candidate, evaluation):
        # archive holds best feasible solution (min cost)
        if evaluation['feasible']:
            if archive['best'] is None or evaluation['cost'] < archive['best_cost']:
                archive['best'] = deepcopy(candidate)
                archive['best_cost'] = evaluation['cost']
        # always store best penalized for selection diversity
        if archive['best_penalized'] is None or evaluation['penalized'] < archive['best_penalized_cost']:
            archive['best_penalized'] = deepcopy(candidate)
            archive['best_penalized_cost'] = evaluation['penalized']

    def _bandit_reward_function(self, old_eval, new_eval):
        # reward positive if penalized cost decreased or feasibility improved
        reward = old_eval['penalized'] - new_eval['penalized']
        # extra bonus if infeasible -> feasible
        if (not old_eval['feasible']) and new_eval['feasible']:
            reward += 1000.0
        return reward

    def _bandit_update(self, bandit, op_name, reward):
        entry = bandit.get(op_name)
        if entry is None:
            # add new op
            bandit[op_name] = {'value': 1.0, 'count': 0}
            entry = bandit[op_name]
        entry['count'] += 1
        # incremental update of estimated value (simple learning rate)
        lr = 1.0 / max(5, entry['count'])
        entry['value'] = (1 - lr) * entry['value'] + lr * reward

    def _migrate(self, populations, islands, policy='random'):
        # simple migration: swap a random individual between random island pairs
        island_count = len(populations)
        if island_count < 2:
            return populations
        a, b = random.sample(range(island_count), 2)
        if not populations[a] or not populations[b]:
            return populations
        ia = random.randrange(len(populations[a]))
        ib = random.randrange(len(populations[b]))
        populations[a][ia], populations[b][ib] = populations[b][ib], populations[a][ia]
        return populations

    def _adapt_operator_pools(self, islands, bandits, archive, adapt_rate=0.1):
        # occasionally replace the worst operator in an island with a copy of the best global operator
        # identify global best operator by average bandit value
        global_vals = {}
        for b in bandits:
            for op, entry in b.items():
                global_vals.setdefault(op, []).append(entry['value'])
        avg_vals = {op: (sum(vs)/len(vs)) for op, vs in global_vals.items()}
        if not avg_vals:
            return
        best_op = max(avg_vals.items(), key=lambda x: x[1])[0]
        for i, isl in enumerate(islands):
            if random.random() < adapt_rate:
                local_ops = isl['operator_portfolio']
                # replace worst local operator with best_op
                if local_ops:
                    # compute local values
                    local_vals = [(op, bandits[i].get(op, {'value':0})['value']) for op in local_ops]
                    worst_op = min(local_vals, key=lambda x: x[1])[0]
                    if worst_op != best_op:
                        # replace
                        isl['operator_portfolio'] = [best_op if o == worst_op else o for o in local_ops]
                        # ensure bandit entry exists
                        if best_op not in bandits[i]:
                            bandits[i][best_op] = {'value': 1.0, 'count': 0}

    # --- main solve method implementing the pseudocode loop ---
    def solve(self) -> list:
        """
        Solve the Capacitated Vehicle Routing Problem (CVRP).

        Returns:
            A one-dimensional list of integers representing the sequence of nodes visited by all vehicles.
        """
        # parameters (tunable)
        island_count = min(4, max(1, self.n // 5))
        per_island_pop = 8
        operator_budget = 1
        parallelism = min(2, island_count)
        migration_interval = 2.0  # seconds
        adapt_rate = 0.12
        time_limit = max(1.0, min(30.0, 0.1 * self.n))  # auto time limit based on instance size

        # init
        seed = int(time.time()) % (2**31 - 1)
        islands = self._init_islands(island_count, seed=seed)
        populations = self._init_population(islands, per_island_pop=per_island_pop)
        archive = {'best': None, 'best_cost': float('inf'), 'best_penalized': None, 'best_penalized_cost': float('inf')}
        bandits = self._init_bandits(islands)

        start = time.time()
        last_migration = start

        # Precompute evaluations for population to speed selection
        pop_evals = []
        for isl_pop in populations:
            evals = [self._evaluate(ind) for ind in isl_pop]
            pop_evals.append(evals)

        # main loop
        while time.time() - start < time_limit:
            # sample islands to operate on
            island_indices = random.sample(range(len(islands)), k=min(parallelism, len(islands)))
            for idx in island_indices:
                island = islands[idx]
                population = populations[idx]
                if not population:
                    continue
                # select parents
                parents = self._select_parents(population, island['focus_profile'])
                # bandit select operators
                ops = self._bandit_select(bandits[idx], budget=operator_budget)
                recomb_op = ops['recombination']
                local_op = ops['local_search']
                # recombine
                offspring = self._recombine_hypergraph(parents, recomb_op)
                # repair
                offspring = self._constraint_propagate_and_repair(offspring)
                # local search
                if local_op == '2opt':
                    offspring = self._local_search_2opt(offspring, time_budget_ms=20)
                elif local_op == 'relocate':
                    offspring = self._local_search_relocate(offspring, time_budget_ms=20)
                else:
                    # minor improvement by 2opt as default
                    offspring = self._local_search_2opt(offspring, time_budget_ms=10)
                # evaluate
                new_eval = self._evaluate(offspring)
                # update archive
                self._archive_update(archive, offspring, new_eval)
                # compute baseline old evaluation: use best penalized in island population as baseline
                # pick parent[0] evaluation if available
                old_eval = self._evaluate(parents[0])
                # reward
                reward = self._bandit_reward_function(old_eval, new_eval)
                # update bandit
                self._bandit_update(bandits[idx], recomb_op, reward)
                # insert offspring into population (replace worst)
                # find worst index by penalized cost
                worst_idx = max(range(len(population)), key=lambda i: self._evaluate(population[i])['penalized'])
                populations[idx][worst_idx] = offspring
                # update pop_evals for this island
                pop_evals[idx] = [self._evaluate(ind) for ind in populations[idx]]

            # migration
            now = time.time()
            if now - last_migration > migration_interval:
                populations = self._migrate(populations, islands)
                last_migration = now

            # adapt operator pools
            self._adapt_operator_pools(islands, bandits, archive, adapt_rate=adapt_rate)

        # decode best solution from archive
        best_routes = archive['best']
        if best_routes is None:
            # fallback to best penalized
            best_routes = archive['best_penalized'] if archive['best_penalized'] is not None else self._init_population(islands, per_island_pop=1)[0]

        flat = self._flatten_solution(best_routes)
        # ensure requirements: start and end at depot, visits all customers exactly once
        # final sanity check/fix
        routes = self._decode_flat(flat)
        routes = self._constraint_propagate_and_repair(routes)
        final_flat = self._flatten_solution(routes)
        return final_flat

