def _makespan(self, sequence: List[int]) -> float:
    """Compute makespan of a permutation sequence (flow shop, permutation schedule).
    Optimized with special-cases for common small numbers of machines and reduced
    attribute lookups for the general case.
    """
    m = self.num_machines
    if m == 0 or not sequence:
        return 0.0

    proc = self.processing_times  # local ref

    # Fast paths for small number of machines (common in benchmarks)
    if m == 1:
        total = 0.0
        for job in sequence:
            total += proc[job][0]
        return float(total)

    if m == 2:
        c0 = 0.0
        c1 = 0.0
        for job in sequence:
            row = proc[job]
            # machine 0
            f0 = c0 + row[0]
            c0 = f0
            # machine 1: start is max(c1, f0)
            if c1 > f0:
                s1 = c1
            else:
                s1 = f0
            c1 = s1 + row[1]
        return float(c1)

    if m == 3:
        c0 = c1 = c2 = 0.0
        for job in sequence:
            row = proc[job]
            f0 = c0 + row[0]
            c0 = f0
            if c1 > f0:
                s1 = c1
            else:
                s1 = f0
            f1 = s1 + row[1]
            c1 = f1
            if c2 > f1:
                s2 = c2
            else:
                s2 = f1
            c2 = s2 + row[2]
        return float(c2)

    # General case for m >= 4
    prev = [0.0] * m
    for job in sequence:
        t0 = 0.0
        row = proc[job]
        # iterate machines updating completion times
        for i in range(m):
            pm = prev[i]
            # start = max(pm, t0) implemented with branch
            if pm > t0:
                start = pm
            else:
                start = t0
            finish = start + row[i]
            prev[i] = finish
            t0 = finish

    return float(prev[-1])

