    Optimized with special-cases for common small numbers of machines and reduced
    attribute lookups for the general case.
    """
    m = int(self.num_machines)
    if m <= 0 or not sequence:
        return 0.0

    proc = self.processing_times  # local reference

    # Fast path: single machine (just sum processing times)
    if m == 1:
        total = 0.0
        for job in sequence:
            total += proc[job][0]
        return float(total)

    # Fast path: two machines
    if m == 2:
        c0 = 0.0
        c1 = 0.0
        for job in sequence:
            row = proc[job]
            f0 = c0 + row[0]
            c0 = f0
            # start on machine 1 is max(c1, f0)
            if c1 < f0:
                c1 = f0 + row[1]
            else:
                c1 = c1 + row[1]
        return float(c1)

    # Fast path: three machines
    if m == 3:
        c0 = 0.0
        c1 = 0.0
        c2 = 0.0
        for job in sequence:
            row = proc[job]
            f0 = c0 + row[0]
            c0 = f0
            if c1 < f0:
                f1 = f0 + row[1]
            else:
                f1 = c1 + row[1]
            c1 = f1
            if c2 < f1:
                c2 = f1 + row[2]
            else:
                c2 = c2 + row[2]
        return float(c2)

    # General case for m >= 4
    prev = [0.0] * m
    rng = range(m)
    for job in sequence:
        row = proc[job]
        t0 = 0.0  # completion time on previous machine for this job
        # update completion times machine by machine
        for i in rng:
            pm = prev[i]
            # start = max(pm, t0)
            if pm > t0:
                start = pm
            else:
                start = t0
            finish = start + row[i]
            prev[i] = finish
            t0 = finish

    return float(prev[-1])

